def co2f(clay): x=1.67*(1.85+1.60*np.exp(-0.0786*clay)); return x/(x+1)
def spin(annual_input,clay,abc,ratio,years=800):
    fco2=co2f(clay); fsoil=1-fco2; fdpm=ratio/(1+ratio)
    p={'DPM':0.,'RPM':0.,'BIO':0.,'HUM':0.}; dt=1/12
    for _ in range(years):
