import warnings; warnings.filterwarnings('ignore'); import numpy as np, time
K=np.array([10.0,0.3,0.66,0.02])
def co2f(c): x=1.67*(1.85+1.60*np.exp(-0.0786*c)); return x/(x+1)
def soc(ai,clay,abc,ratio,years=600):
    fs=1-co2f(clay); fd=ratio/(1+ratio); dt=1/12; dec=np.exp(-abc*K*dt)
    add=np.array([fd,1-fd,0,0])*(ai/12); p=np.zeros(4)
    for _ in range(years*12):
        a=p*dec; d=(p-a).sum()*fs; a[2]+=0.46*d; a[3]+=0.54*d; p=a+add
    return p.sum()
from SALib.sample import sobol as sa_s; from SALib.analyze import sobol as sa_a
prob={'num_vars':4,'names':['input','clay','abc','ratio'],'bounds':[[1,4],[5,50],[0.2,0.5],[0.25,2.0]]}
for trial in [1,2]:
    X=sa_s.sample(prob,128,seed=42)         # 固定种子
    Y=np.array([soc(*x) for x in X])
    Si=sa_a.analyze(prob,Y,seed=42,print_to_console=False)
    print(f'trial{trial}: runs={len(X)}  S1=', {n:round(float(s),3) for n,s in zip(prob['names'],Si['S1'])})
" 2>&1 | tail -4

